// type: AND2B1 
`timescale 1ns/10ps
`celldefine
module AND2B1X1 (O, B2, I1);
	output O;
	input B2, I1;

	// Function
	wire B2__bar;

	not (B2__bar, B2);
	and (O, I1, B2__bar);

	// Timing
	specify
		(B2 => O) = 0;
		(I1 => O) = 0;
	endspecify
endmodule
`endcelldefine

