// type: DFFCKBQ 
`timescale 1ns/10ps
`celldefine
module DFFCKBQX1 (Q, D, CKB);
	output Q;
	input D, CKB;
	reg notifier;
	wire delayed_D, delayed_CKB;

	// Function
	wire int_fwire_clk, int_fwire_IQ, xcr_0;

	not (int_fwire_clk, delayed_CKB);
	altos_dff_err (xcr_0, int_fwire_clk, delayed_D);
	altos_dff (int_fwire_IQ, notifier, int_fwire_clk, delayed_D, xcr_0);
	buf (Q, int_fwire_IQ);

	// Timing
	specify
		(negedge CKB => (Q+:D)) = 0;
		$setuphold (negedge CKB, posedge D, 0, 0, notifier,,, delayed_CKB, delayed_D);
		$setuphold (negedge CKB, negedge D, 0, 0, notifier,,, delayed_CKB, delayed_D);
		$width (posedge CKB &&& D == 1'b1, 0, 0, notifier);
		$width (negedge CKB &&& D == 1'b1, 0, 0, notifier);
		$width (posedge CKB &&& D == 1'b0, 0, 0, notifier);
		$width (negedge CKB &&& D == 1'b0, 0, 0, notifier);
	endspecify
endmodule
`endcelldefine

