// type: DFFCKBRBQB 
`timescale 1ns/10ps
`celldefine
module DFFCKBRBQBX1 (QB, D, RB, CKB);
	output QB;
	input D, RB, CKB;
	reg notifier;
	wire delayed_D, delayed_CKB;

	// Function
	wire int_fwire_clk, int_fwire_IQ, int_fwire_IQN;
	wire int_fwire_r, xcr_0;

	not (int_fwire_clk, delayed_CKB);
	not (int_fwire_r, RB);
	altos_dff_r_err (xcr_0, int_fwire_clk, delayed_D, int_fwire_r);
	altos_dff_r (int_fwire_IQ, notifier, int_fwire_clk, delayed_D, int_fwire_r, xcr_0);
	not (int_fwire_IQN, int_fwire_IQ);
	buf (QB, int_fwire_IQN);

	// Timing

	// Additional timing wires
	wire adacond0, adacond1, adacond2;
	wire adacond3, adacond4, adacond5;
	wire CKB__bar, D__bar;


	// Additional timing gates
	and (adacond0, CKB, D);
	not (D__bar, D);
	and (adacond1, CKB, D__bar);
	not (CKB__bar, CKB);
	and (adacond2, CKB__bar, D);
	and (adacond3, CKB__bar, D__bar);
	and (adacond4, D, RB);
	and (adacond5, D__bar, RB);

	specify
		if (CKB == 1'b1 && D == 1'b1)
			(negedge RB => (QB-:1'b0)) = 0;
		if (CKB == 1'b1 && D == 1'b0)
			(negedge RB => (QB-:1'b0)) = 0;
		if (CKB == 1'b0 && D == 1'b1)
			(negedge RB => (QB-:1'b0)) = 0;
		if (CKB == 1'b0 && D == 1'b0)
			(negedge RB => (QB-:1'b0)) = 0;
		ifnone (negedge RB => (QB-:1'b0)) = 0;
		(negedge CKB => (QB-:D)) = 0;
		$setuphold (negedge CKB &&& RB == 1'b1, posedge D &&& RB == 1'b1, 0, 0, notifier,,, delayed_CKB, delayed_D);
		$setuphold (negedge CKB &&& RB == 1'b1, negedge D &&& RB == 1'b1, 0, 0, notifier,,, delayed_CKB, delayed_D);
		$recovery (posedge RB &&& D == 1'b1, negedge CKB &&& D == 1'b1, 0, notifier);
		$hold (negedge CKB &&& D == 1'b1, posedge RB &&& D == 1'b1, 0, notifier);
		$width (negedge RB &&& adacond0, 0, 0, notifier);
		$width (negedge RB &&& adacond1, 0, 0, notifier);
		$width (negedge RB &&& adacond2, 0, 0, notifier);
		$width (negedge RB &&& adacond3, 0, 0, notifier);
		$width (posedge CKB &&& adacond4, 0, 0, notifier);
		$width (negedge CKB &&& adacond4, 0, 0, notifier);
		$width (posedge CKB &&& adacond5, 0, 0, notifier);
		$width (negedge CKB &&& adacond5, 0, 0, notifier);
	endspecify
endmodule
`endcelldefine

// type: DFFCKBRBQB 
`timescale 1ns/10ps
`celldefine
module DFFCKBRBQBX2 (QB, D, RB, CKB);
	output QB;
	input D, RB, CKB;
	reg notifier;
	wire delayed_D, delayed_CKB;

	// Function
	wire int_fwire_clk, int_fwire_IQ, int_fwire_IQN;
	wire int_fwire_r, xcr_0;

	not (int_fwire_clk, delayed_CKB);
