	wire D__bar, int_twire_0;


	// Additional timing gates
	and (adacond0, CN, D);
	not (CN__bar, CN);
	not (D__bar, D);
	and (int_twire_0, CN, D__bar);
	or (adacond1, int_twire_0, CN__bar);

