module MUX3X4 (O, I0, I1, I2, S0, S1);
	output O;
	input I0, I1, I2, S0, S1;

	// Function
	wire I0__bar, I1__bar, I2__bar;
	wire int_fwire_0, int_fwire_1, int_fwire_2;
	wire int_fwire_3, int_fwire_4, int_fwire_5;
	wire S0__bar, S1__bar;

	not (S1__bar, S1);
	not (S0__bar, S0);
	not (I2__bar, I2);
	and (int_fwire_0, I2__bar, S0__bar, I0, S1__bar);
	and (int_fwire_1, I2__bar, S0, I1, S1__bar);
	not (I0__bar, I0);
	and (int_fwire_2, I2, S0__bar, I0__bar, S1);
	and (int_fwire_3, I2, S0__bar, I0);
	not (I1__bar, I1);
	and (int_fwire_4, I2, S0, I1__bar, S1);
	and (int_fwire_5, I2, S0, I1);
	or (O, int_fwire_5, int_fwire_4, int_fwire_3, int_fwire_2, int_fwire_1, int_fwire_0);

	// Timing
	specify
		(I0 => O) = 0;
		(I1 => O) = 0;
		(I2 => O) = 0;
		if (I0 == 1'b0 && I1 == 1'b1 && S1 == 1'b0)
			(S0 => O) = 0;
		ifnone (S0 => O) = 0;
		if (I0 == 1'b1 && I1 == 1'b0 && S1 == 1'b0)
			(S0 => O) = 0;
		if (((I0 == 1'b1) && (I1 == 1'b0) && (I2 == 1'b1) && (S0 == 1'b1))  |  ((I0 == 1'b0) && (I1 == 1'b1) && (I2 == 1'b1) && (S0 == 1'b0))  |  ((I0 == 1'b0) && (I1 == 1'b0) && (I2 == 1'b1)))
			(S1 => O) = 0;
		ifnone (S1 => O) = 0;
		if (((I0 == 1'b1) && (I1 == 1'b1) && (I2 == 1'b0))  |  ((I0 == 1'b1) && (I1 == 1'b0) && (I2 == 1'b0) && (S0 == 1'b0))  |  ((I0 == 1'b0) && (I1 == 1'b1) && (I2 == 1'b0) && (S0 == 1'b1)))
			(S1 => O) = 0;
	endspecify
endmodule
