// type: MUXLATCH 
`timescale 1ns/10ps
`celldefine
module MUXLATCHX1 (Q, QB, D1, D2, SEL, CL);
	output Q, QB;
	input D1, D2, SEL, CL;
	reg notifier;
	wire delayed_D1, delayed_D2, delayed_SEL, delayed_CL;

	// Function
	wire delayed_SEL__bar, int_fwire_0, int_fwire_1;
	wire int_fwire_d, int_fwire_IQ, int_fwire_IQB;

	not (delayed_SEL__bar, delayed_SEL);
	and (int_fwire_0, delayed_SEL__bar, delayed_D1);
	and (int_fwire_1, delayed_SEL, delayed_D2);
	or (int_fwire_d, int_fwire_1, int_fwire_0);
	altos_latch (int_fwire_IQ, notifier, delayed_CL, int_fwire_d);
	buf (Q, int_fwire_IQ);
	not (int_fwire_IQB, int_fwire_IQ);
	buf (QB, int_fwire_IQB);

	// Timing

	// Additional timing wires
	wire adacond0, adacond1, adacond2;
	wire adacond3, adacond4, adacond5;
	wire adacond6, adacond7, D1__bar;
	wire D2__bar, int_twire_0, int_twire_1;
	wire int_twire_2, int_twire_3, int_twire_4;
	wire int_twire_5, SEL__bar;


	// Additional timing gates
	not (SEL__bar, SEL);
	and (adacond0, D2, SEL__bar);
	not (D2__bar, D2);
	and (adacond1, D2__bar, SEL__bar);
	and (adacond2, D1, SEL);
	not (D1__bar, D1);
	and (adacond3, D1__bar, SEL);
	and (adacond4, D1, D2__bar);
	and (adacond5, D1__bar, D2);
	and (int_twire_0, D1__bar, D2, SEL);
	and (int_twire_1, D1, D2__bar, SEL__bar);
	and (int_twire_2, D1, D2);
	or (adacond6, int_twire_2, int_twire_1, int_twire_0);
	and (int_twire_3, D1__bar, D2__bar);
	and (int_twire_4, D1__bar, D2, SEL__bar);
	and (int_twire_5, D1, D2__bar, SEL);
	or (adacond7, int_twire_5, int_twire_4, int_twire_3);

	specify
		if (CL == 1'b1 && D2 == 1'b1 && SEL == 1'b0)
			(D1 => Q) = 0;
		if (CL == 1'b1 && D2 == 1'b0 && SEL == 1'b0)
			(D1 => Q) = 0;
		ifnone (D1 => Q) = 0;
		if (CL == 1'b1 && D1 == 1'b1 && SEL == 1'b1)
			(D2 => Q) = 0;
		if (CL == 1'b1 && D1 == 1'b0 && SEL == 1'b1)
			(D2 => Q) = 0;
		ifnone (D2 => Q) = 0;
		if (CL == 1'b1 && D1 == 1'b0 && D2 == 1'b1)
			(SEL => Q) = 0;
		ifnone (SEL => Q) = 0;
		if (CL == 1'b1 && D1 == 1'b1 && D2 == 1'b0)
			(SEL => Q) = 0;
		if (((D1 == 1'b1) && (D2 == 1'b1))  |  ((D1 == 1'b1) && (D2 == 1'b0) && (SEL == 1'b0))  |  ((D1 == 1'b0) && (D2 == 1'b1) && (SEL == 1'b1)))
			(posedge CL => (Q+:((D1 && D2) || (D1 && !D2 && !SEL) || (!D1 && D2 && SEL)))) = 0;
		if (((D1 == 1'b1) && (D2 == 1'b0) && (SEL == 1'b1))  |  ((D1 == 1'b0) && (D2 == 1'b1) && (SEL == 1'b0))  |  ((D1 == 1'b0) && (D2 == 1'b0)))
			(posedge CL => (Q+:((D1 && D2) || (D1 && !D2 && !SEL) || (!D1 && D2 && SEL)))) = 0;
		ifnone (posedge CL => (Q+:((D1 && D2) || (D1 && !D2 && !SEL) || (!D1 && D2 && SEL)))) = 0;
		if (CL == 1'b1 && D2 == 1'b1 && SEL == 1'b0)
			(D1 => QB) = 0;
		if (CL == 1'b1 && D2 == 1'b0 && SEL == 1'b0)
			(D1 => QB) = 0;
		ifnone (D1 => QB) = 0;
		if (CL == 1'b1 && D1 == 1'b1 && SEL == 1'b1)
			(D2 => QB) = 0;
