			(SEL => QB) = 0;
		if (((D1 == 1'b1) && (D2 == 1'b1))  |  ((D1 == 1'b1) && (D2 == 1'b0) && (SEL == 1'b0))  |  ((D1 == 1'b0) && (D2 == 1'b1) && (SEL == 1'b1)))
			(posedge CL => (QB-:((D1 && D2) || (D1 && !D2 && !SEL) || (!D1 && D2 && SEL)))) = 0;
		if (((D1 == 1'b1) && (D2 == 1'b0) && (SEL == 1'b1))  |  ((D1 == 1'b0) && (D2 == 1'b1) && (SEL == 1'b0))  |  ((D1 == 1'b0) && (D2 == 1'b0)))
			(posedge CL => (QB-:((D1 && D2) || (D1 && !D2 && !SEL) || (!D1 && D2 && SEL)))) = 0;
		ifnone (posedge CL => (QB-:((D1 && D2) || (D1 && !D2 && !SEL) || (!D1 && D2 && SEL)))) = 0;
		$setuphold (negedge CL &&& adacond0, posedge D1 &&& adacond0, 0, 0, notifier,,, delayed_CL, delayed_D1);
		$setuphold (negedge CL &&& adacond0, negedge D1 &&& adacond0, 0, 0, notifier,,, delayed_CL, delayed_D1);
		$setuphold (negedge CL &&& adacond1, posedge D1 &&& adacond1, 0, 0, notifier,,, delayed_CL, delayed_D1);
		$setuphold (negedge CL &&& adacond1, negedge D1 &&& adacond1, 0, 0, notifier,,, delayed_CL, delayed_D1);
