module OAI22X4 (O, A1, A2, B1, B2);
	output O;
	input A1, A2, B1, B2;

	// Function
	wire int_fwire_0, int_fwire_1, int_fwire_2;

	or (int_fwire_0, B1, B2);
	or (int_fwire_1, A1, A2);
	and (int_fwire_2, int_fwire_1, int_fwire_0);
	not (O, int_fwire_2);

	// Timing
	specify
		if (A2 == 1'b0 && B1 == 1'b1 && B2 == 1'b1)
			(A1 => O) = 0;
		if (A2 == 1'b0 && B1 == 1'b1 && B2 == 1'b0)
			(A1 => O) = 0;
		if (A2 == 1'b0 && B1 == 1'b0 && B2 == 1'b1)
			(A1 => O) = 0;
		ifnone (A1 => O) = 0;
		if (A1 == 1'b0 && B1 == 1'b1 && B2 == 1'b1)
			(A2 => O) = 0;
		if (A1 == 1'b0 && B1 == 1'b1 && B2 == 1'b0)
			(A2 => O) = 0;
		if (A1 == 1'b0 && B1 == 1'b0 && B2 == 1'b1)
			(A2 => O) = 0;
		ifnone (A2 => O) = 0;
		if (A1 == 1'b1 && A2 == 1'b1 && B2 == 1'b0)
			(B1 => O) = 0;
		if (A1 == 1'b1 && A2 == 1'b0 && B2 == 1'b0)
			(B1 => O) = 0;
		if (A1 == 1'b0 && A2 == 1'b1 && B2 == 1'b0)
			(B1 => O) = 0;
		ifnone (B1 => O) = 0;
		if (A1 == 1'b1 && A2 == 1'b1 && B1 == 1'b0)
			(B2 => O) = 0;
		if (A1 == 1'b1 && A2 == 1'b0 && B1 == 1'b0)
			(B2 => O) = 0;
		if (A1 == 1'b0 && A2 == 1'b1 && B1 == 1'b0)
			(B2 => O) = 0;
		ifnone (B2 => O) = 0;
	endspecify
endmodule
`endcelldefine

