`timescale 1ns/10ps
`celldefine
module SFFCKBQX1 (Q, D, SEL, TD, CKB);
	output Q;
	input D, SEL, TD, CKB;
	reg notifier;
	wire delayed_D, delayed_SEL, delayed_TD, delayed_CKB;

	// Function
	wire int_fwire_clk, int_fwire_d, int_fwire_IQ;
	wire xcr_0;

	altos_mux2 (int_fwire_d, delayed_D, delayed_TD, delayed_SEL);
	not (int_fwire_clk, delayed_CKB);
	altos_dff_err (xcr_0, int_fwire_clk, int_fwire_d);
	altos_dff (int_fwire_IQ, notifier, int_fwire_clk, int_fwire_d, xcr_0);
	buf (Q, int_fwire_IQ);

	// Timing

	// Additional timing wires
	wire adacond0, adacond1, adacond2;
	wire adacond3, adacond4, adacond5;
	wire adacond6, adacond7, adacond8;
	wire adacond9, adacond10, adacond11;
	wire adacond12, adacond13, D__bar;
	wire SEL__bar, TD__bar;


	// Additional timing gates
	not (SEL__bar, SEL);
	and (adacond0, SEL__bar, TD);
	not (TD__bar, TD);
	and (adacond1, SEL__bar, TD__bar);
	and (adacond2, D, TD__bar);
	not (D__bar, D);
	and (adacond3, D__bar, TD);
	and (adacond4, D, SEL);
	and (adacond5, D__bar, SEL);
	and (adacond6, D, SEL, TD);
	and (adacond7, D, SEL, TD__bar);
	and (adacond8, D, SEL__bar, TD);
	and (adacond9, D, SEL__bar, TD__bar);
	and (adacond10, D__bar, SEL, TD);
	and (adacond11, D__bar, SEL, TD__bar);
	and (adacond12, D__bar, SEL__bar, TD);
	and (adacond13, D__bar, SEL__bar, TD__bar);

	specify
		(negedge CKB => (Q+:((SEL && TD) || (!SEL && D)))) = 0;
		$setuphold (negedge CKB &&& adacond0, posedge D &&& adacond0, 0, 0, notifier,,, delayed_CKB, delayed_D);
		$setuphold (negedge CKB &&& adacond0, negedge D &&& adacond0, 0, 0, notifier,,, delayed_CKB, delayed_D);
		$setuphold (negedge CKB &&& adacond1, posedge D &&& adacond1, 0, 0, notifier,,, delayed_CKB, delayed_D);
		$setuphold (negedge CKB &&& adacond1, negedge D &&& adacond1, 0, 0, notifier,,, delayed_CKB, delayed_D);
		$setuphold (negedge CKB &&& adacond2, posedge SEL &&& adacond2, 0, 0, notifier,,, delayed_CKB, delayed_SEL);
		$setuphold (negedge CKB &&& adacond2, negedge SEL &&& adacond2, 0, 0, notifier,,, delayed_CKB, delayed_SEL);
