		$setuphold (negedge CKB &&& adacond3, negedge SEL &&& adacond3, 0, 0, notifier,,, delayed_CKB, delayed_SEL);
		$setuphold (negedge CKB &&& adacond4, posedge TD &&& adacond4, 0, 0, notifier,,, delayed_CKB, delayed_TD);
		$setuphold (negedge CKB &&& adacond4, negedge TD &&& adacond4, 0, 0, notifier,,, delayed_CKB, delayed_TD);
		$setuphold (negedge CKB &&& adacond5, posedge TD &&& adacond5, 0, 0, notifier,,, delayed_CKB, delayed_TD);
		$setuphold (negedge CKB &&& adacond5, negedge TD &&& adacond5, 0, 0, notifier,,, delayed_CKB, delayed_TD);
		$width (posedge CKB &&& adacond6, 0, 0, notifier);
		$width (negedge CKB &&& adacond6, 0, 0, notifier);
		$width (posedge CKB &&& adacond7, 0, 0, notifier);
		$width (negedge CKB &&& adacond7, 0, 0, notifier);
		$width (posedge CKB &&& adacond8, 0, 0, notifier);
		$width (negedge CKB &&& adacond8, 0, 0, notifier);
		$width (posedge CKB &&& adacond9, 0, 0, notifier);
		$width (negedge CKB &&& adacond9, 0, 0, notifier);
		$width (posedge CKB &&& adacond10, 0, 0, notifier);
		$width (negedge CKB &&& adacond10, 0, 0, notifier);
		$width (posedge CKB &&& adacond11, 0, 0, notifier);
		$width (negedge CKB &&& adacond11, 0, 0, notifier);
		$width (posedge CKB &&& adacond12, 0, 0, notifier);
		$width (negedge CKB &&& adacond12, 0, 0, notifier);
		$width (posedge CKB &&& adacond13, 0, 0, notifier);
		$width (negedge CKB &&& adacond13, 0, 0, notifier);
	endspecify
endmodule
