	wire adacond30, adacond31, adacond32;
	wire adacond33, CK__bar, D__bar;
	wire SEL__bar, TD__bar;


	// Additional timing gates
	not (SEL__bar, SEL);
	and (adacond0, SB, SEL__bar, TD);
	not (TD__bar, TD);
	and (adacond1, SB, SEL__bar, TD__bar);
