	and (adacond17, CK, D__bar, SEL__bar, TD__bar);
	not (CK__bar, CK);
	and (adacond18, CK__bar, D, SEL, TD);
	and (adacond19, CK__bar, D, SEL, TD__bar);
	and (adacond20, CK__bar, D, SEL__bar, TD);
	and (adacond21, CK__bar, D, SEL__bar, TD__bar);
	and (adacond22, CK__bar, D__bar, SEL, TD);
