	and (adacond25, CK__bar, D__bar, SEL__bar, TD__bar);
	and (adacond26, D, SB, SEL, TD);
	and (adacond27, D, SB, SEL, TD__bar);
	and (adacond28, D, SB, SEL__bar, TD);
	and (adacond29, D, SB, SEL__bar, TD__bar);
