	and (adacond32, D__bar, SB, SEL__bar, TD);
	and (adacond33, D__bar, SB, SEL__bar, TD__bar);

	specify
		if (CK == 1'b1 && D == 1'b1 && SEL == 1'b1 && TD == 1'b1)
			(negedge SB => (Q+:1'b1)) = 0;
		if (CK == 1'b1 && D == 1'b1 && SEL == 1'b1 && TD == 1'b0)
			(negedge SB => (Q+:1'b1)) = 0;
