			(negedge SB => (Q+:1'b1)) = 0;
		if (CK == 1'b0 && D == 1'b1 && SEL == 1'b0 && TD == 1'b1)
			(negedge SB => (Q+:1'b1)) = 0;
		if (CK == 1'b0 && D == 1'b1 && SEL == 1'b0 && TD == 1'b0)
